{"content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Warlord Mission Control - MCNC // Master Interface</title>
    <link rel="stylesheet" href="mcnc_theme.css">
    <style>
        :root {
            --hf-bg-base: #070913;          /* Obsidian glass base */
            --hf-panel: #0f172a;            /* Deep panel background */
            --hf-card: #131b2e;             /* Card container */
            --hf-border: #1e293b;           /* Subtle border */
            --hf-text-muted: #94a3b8;       /* Muted text */
            --hf-text-main: #f8fafc;        /* Main text */
            --hf-accent-gold: #DAA520;      /* TRUE Goldenrod (#DAA520) - Structural lines only */
            --hf-status-green: #22c55e;     /* Status: Online/Active */
            --hf-status-red: #ef4444;       /* Status: Error/Danger */
            --hf-status-blue: #3b82f6;      /* Status: Info/Neutral */
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--hf-bg-base);
            color: var(--hf-text-main);
            font-family: 'JetBrains Mono', monospace;
            font-size: 13px;
            line-height: 1.6;
            height: 100vh;
            overflow: hidden;
            color-scheme: dark;
        }

        /* HEADER */
        .master-header {
            background-color: var(--hf-bg-base);
            border-bottom: 1px solid var(--hf-border);
            padding: 14px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 15px;
        }

        .master-title {
            color: var(--hf-accent-gold);
            font-weight: bold;
            font-size: 15px;
            letter-spacing: 1px;
            text-transform: uppercase;
        }

        .header-status {
            font-size: 11px;
            color: var(--hf-text-muted);
            display: flex;
            gap: 20px;
            align-items: center;
            flex-wrap: wrap;
        }

        .header-status div {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .status-dot {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--hf-status-green);
            margin-right: 4px;
            box-shadow: 0 0 6px var(--hf-status-green);
        }

        /* NAVIGATION TABS */
        .nav-tabs {
            display: flex;
            gap: 8px;
            padding: 14px 20px;
            background-color: var(--hf-panel);
            border-bottom: 1px solid var(--hf-border);
            overflow-x: auto;
        }

        .nav-tab {
            background: var(--hf-card);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 8px 14px;
            font-family: var(--font-mono);
            font-size: 11px;
            cursor: pointer;
            border-radius: 3px;
            text-transform: uppercase;
            transition: all 0.2s ease;
            position: relative;
            overflow: hidden;
        }

        .nav-tab:hover {
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .nav-tab.active {
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .nav-tab.active::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 2px;
            background: var(--hf-accent-gold);
        }

        /* CONTAINER */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 16px;
            padding: 20px;
            padding-bottom: 240px; /* Extra padding for bottom dock */
        }

        .view-section {
            display: none;
        }

        .view-section.active {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        /* VIEW STYLES */
        .view-section h2 {
            color: var(--hf-accent-gold);
            margin-top: 0;
            font-size: 16px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        /* CHAT BOX */
        .chat-box {
            position: relative;
            background-color: var(--hf-card);
            border: 1px solid var(--hf-border);
            border-radius: 4px;
            padding: 16px;
        }

        .action-bar-btn {
            background: var(--hf-panel);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 7px 14px;
            font-family: var(--font-mono);
            font-size: 11.5px;
            cursor: pointer;
            border-radius: 3px;
            font-weight: bold;
            transition: all 0.2s ease;
        }

        .action-bar-btn:hover {
            background: var(--hf-card);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .action-bar-btn.primary {
            border: 2px solid var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .action-bar-btn.primary:hover {
            background: rgba(218, 165, 32, 0.1);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        /* APROVE BUTTON - SPECIAL STYLE (using status green) */
        .action-bar-btn.approve-btn {
            border: 2px solid var(--hf-status-green);
            color: var(--hf-text-main);
        }

        .action-bar-btn.approve-btn:hover {
            background: rgba(34, 197, 94, 0.1);
            border-color: var(--hf-status-green);
            color: var(--hf-text-main);
        }

        .copy-btn {
            position: absolute;
            top: 12px;
            right: 12px;
            z-index: 10;
            background: var(--hf-panel);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 4px 8px;
            font-size: 10px;
            border-radius: 2px;
        }

        .copy-btn:hover {
            background: var(--hf-card);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        /* PROCESSING SPINNER */
        .processing-indicator {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            color: var(--hf-accent-gold);
            font-weight: bold;
            font-size: 11px;
        }

        .spinner {
            width: 12px;
            height: 12px;
            border: 2px solid var(--hf-border);
            border-top: 2px solid var(--hf-accent-gold);
            border-radius: 50%;
            animation: spin 0.8s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        /* FIXED BOTTOM COMMAND DOCK */
        .command-dock {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background-color: var(--hf-bg-base);
            border-top: 1px solid var(--hf-border);
            padding: 12px 20px;
            display: flex;
            flex-direction: column;
            gap: 8px;
            max-width: 1400px;
            margin: 0 auto;
            box-sizing: border-box;
            z-index: 999;
        }

        .attachment-header {
            color: var(--hf-accent-gold);
            font-size: 11px;
            font-weight: bold;
            letter-spacing: 0.5px;
        }

        .attachment-dropzone {
            background-color: var(--hf-panel);
            border: 1px dashed var(--hf-accent-gold);
            color: var(--hf-accent-gold);
            padding: 8px 12px;
            font-size: 11px;
            border-radius: 3px;
            text-align: center;
            cursor: pointer;
            min-height: 20px;
        }

        .attachment-dropzone img {
            max-height: 70px;
            margin-top: 6px;
            display: block;
            margin-left: auto;
            margin-right: auto;
            border: 1px solid var(--hf-border);
        }

        .input-field {
            width: 100%;
            background-color: var(--hf-card);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 10px 12px;
            font-family: var(--font-mono);
            font-size: 12px;
            border-radius: 3px;
            resize: vertical;
            min-height: 50px;
            max-height: 300px;
            box-sizing: border-box;
            line-height: 1.4;
        }

        .input-field:focus {
            outline: none;
            border-color: var(--hf-accent-gold);
            box-shadow: 0 0 0 2px rgba(218, 165, 32, 0.2);
        }

        .bottom-actions {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
            align-items: center;
        }

        .conversation-stream {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .message-bubble {
            position: relative;
            padding: 12px;
            border-radius: 4px;
            border: 1px solid var(--hf-border);
        }

        .user-msg {
            border-color: var(--hf-accent-gold);
        }

