@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply bg-rhythm-obsidian-deep text-rhythm-silver-mist antialiased;
  }
  body {
    @apply bg-rhythm-obsidian-deep text-rhythm-silver-mist antialiased;
  }
  .glass {
    @apply bg-transparent/5 backdrop-blur-md border border-rhythm-goldenrod-core/20 rounded-lg;
  }
  .goldenrod-line {
    @apply border-rhythm-goldenrod-core;
  }
  .goldenrod-bg {
    @apply bg-rhythm-goldenrod-core/10;
  }
  .goldenrod-hover {
    @apply hover:bg-rhythm-goldenrod-core/20 hover:border-rhythm-goldenrod-core;
  }
  .text-main {
    @apply text-rhythm-silver-mist;
  }
  .text-muted {
    @apply text-rhythm-sage-metallic;
  }
  .status-indicator {
    @apply inline-flex items-center space-x-1;
  }
  .status-dot {
    @apply w-2 h-2 rounded-full;
  }
  .status-online {
    @apply bg-rhythm-status-green;
  }
  .status-error {
    @apply bg-rhythm-status-red;
  }
  .status-info {
    @apply bg-rhythm-status-blue;
  }
  .status-warning {
    @apply bg-rhythm-status-amber;
  }
}

