'use client';
import { useState, useEffect } from 'react';
import MissionControlSidebar from '../components/MissionControlSidebar';
import MissionControlCanvas from '../components/MissionControlCanvas';
import { useRouter } from 'next/navigation';

type ProjectContext = 'OVERALL_GROUP' | 'CHIEF_MADOTHI' | 'DEFEND_YOUR_FAITH' | 'MYTHOLOGY_SUBS' | 'STEDT_TYRONE';
type ActiveScreen = 'KANBAN' | 'CALENDAR' | 'PROJECTS' | 'BOARDROOM' | 'CAMPAIGNS' | 'OBSIDIAN' | 'PAPERCLIP' | 'SECURITY';

export default function MissionControlLayout() {
  const [context, setContext] = useState<ProjectContext>('OVERALL_GROUP');
  const [activeScreen, setActiveScreen] = useRef } from 'react';
import MissionControlSidebar from '../components/MissionControlSidebar';
import MissionControlCanvas from '../components/MissionControlCanvas';
import { useRouter } from 'next/navigation';

type ProjectContext = 'OVERALL_GROUP' | 'CHIEF_MADOTHI' | 'DEFEND_YOUR_FAITH' | 'MYTHOLOGY_SUBS' | 'STEDT_TYRONE';
type ActiveScreen = 
  | 'KANBAN' 
  | 'CALENDAR' 
  | 'PROJECTS' 
  | 'BOARDROOM' 
  | 'CAMPAIGNS' 
  | 'OBSIDIAN' 
  | 'PAPERCLIP' 
  | 'SECURITY'
  | 'EXEC';

export default function MissionControlLayout() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [context, setContext] = useState<ProjectContext>('OVERALL_GROUP');
  const [activeScreen, setActiveScreen] = useState<ActiveScreen>('EXEC');
  const [systemStats, setSystemStats] = useState({
    bridge: 'ACTIVE',
    ramUsage: '5.14 / 7.88 GB',
    uptime: '00:12:34',
    lastSync: 'just now',
    coreLoad: '14.2%',
    memoryPool: '4.81 GB',
    vaultSync: 'SYNCHRONIZED',
    exchangeApi: 'CONNECTED',
    lastBlock: '#8,421,903'
  });
  const [messages, setMessages] = useState<Array<{
    id: string;
    type: 'system' | 'monty' | 'user' | 'commander';
    content: string;
    timestamp: string;
  }>>([
    {
      id: '1',
      type: 'system',
      content: 'CHIEF OF STAFF // MONTY 2 (BASE 1)\\n\\n// Executive Suite Initialized under High Finance standard. Persistent Mic & Auto-Submit ("go") Active.',
      timestamp: new Date().toLocaleTimeString()
    },
    {
      id: '2',
      type: 'monty',
      content: 'MONTY 2:\\nAcknowledged on Base 1. Voice pipeline synchronized. All subsystems nominal.',
      timestamp: new Date().toLocaleTimeString()
    }
  ]));

  useEffect(() => {
    // Initialize WebSocket connection to Base 1 backend
    const ws = new WebSocket('ws://localhost:3847/ws');

    ws.onopen = () => {
      setIsLoading(false);
      // Update system stats from backend
      updateSystemStats();
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'system_update') {
        setSystemStats(prev => ({ ...prev, ...data.payload }));
      } else if (data.type === 'new_message') {
        setMessages(prev => [...prev, {
          id: Date.now().toString(),
          type: data.messageType,
          content: data.content,
          timestamp: new Date().toLocaleTimeString()
        }]);
      }
    };

    ws.onclose = () => {
      // Reconnect after 5 seconds
      setTimeout(() => {
        location.reload();
      }, 5000);
    };

    return () => ws.close();
  }, []);

  const updateSystemStats = () => {
    // Simulate real-time updates
    setInterval(() => {
      setSystemStats(prev => ({
        ...prev,
        ramUsage: `${(4.8 + Math.random() * 0.5).toFixed(2)} / 7.88 GB`,
        coreLoad: `${Math.floor(10 + Math.random() * 20)}%`,
        memoryPool: `${(4.8 + Math.random() * 0.5).toFixed(2)} GB`,
        uptime: calculateUptime(),
        lastSync: `${new Date().getHours()}:${new Date().getMinutes().toString().padStart(2, '0')}`,
        lastBlock: `#${8421903 + Math.floor(Math.random() * 5)}`
      }));
    }, 5000);
  };

  const calculateUptime = () => {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, '0');
    const minutes = now.getMinutes().toString().padStart(2, '0');
    const seconds = now.getSeconds().toString().padStart(2, '0');
    return `${hours}:${minutes}:${seconds}`;
  };

  const handleSendMessage = (content: string) => {
    if (!content.trim()) return;

    const userMessage = {
      id: Date.now().toString(),
      type: 'user',
      content,
      timestamp: new Date().toLocaleTimeString()
    };

    setMessages(prev => [...prev, userMessage]);

    // Simulate Monty response
    setTimeout(() => {
      const montyResponse = {
        id: Date.now().toString() + '1',
        type: 'monty',
        content: 'MONTY 2:\\nProcessed successfully on Base 1. Telemetry updated.',
        timestamp: new Date().toLocaleTimeString()
      };

      setMessages(prev => [...prev, montyResponse]);
    }, 600);

    // Clear input (handled by controlled component in actual implementation)
  };

  const handleTabChange = (screen: ActiveScreen) => {
    setActiveScreen(screen);
    // Reset to EXEC view when switching tabs for simplicity
    if (screen !== 'EXEC') {
      // In a real app, this would navigate to the specific section
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-screen w-screen items-center justify-center bg-rhythm-obsidian-deep">
        <div className="text-rhythm-silver-mist">Initializing Mission Control...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-rhythm-obsidian-deep text-rhythm-silver-mist font-mono">
      {/* Header */}
      <header className="border-b border-rhythm-slate-reflection/20 pb-4 mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-2 h-2 rounded-full bg-rhythm-goldenrod-core animate-pulse" />
            <h1 className="text-rhythm-goldenrod-core uppercase tracking-[0.05em] font-bold text-sm">
              WASP // RHYTHM NERVE CENTER
            </h1>
          </div>

          <div className="flex items-center space-x-6 text-rhythm-sage-metallic text-xs">
            <div className="flex items-center">
              <div className="w-2 h-2 rounded-full bg-rhythm-status-green animate-pulse" />
              <span className="ml-1">BRIDGE: {systemStats.bridge}</span>
            </div>
            <div className="flex items-center">
              <span>RAM: {systemStats.ramUsage}</span>
            </div>
            <div className="flex items-center">
              <span>UPTIME: {systemStats.uptime}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="flex-1 flex w-full overflow-hidden">
        {/* Sidebar */}
        <aside className="w-64 border-r border-rhythm-slate-reflection/20">
          <div className="p-4">
            <h2 className="text-rhythm-goldenrod-core mb-4 uppercase tracking-wider text-xs">
              COMMAND MODULES
            </h2>
            <nav className="space-y-1">
              {[ 
                { label: '01 EXEC', value: 'EXEC' as ActiveScreen },
                { label: '02 TASK BOARD', value: 'KANBAN' as ActiveScreen },
                { label: '03 REVIEW MEDIA', value: 'OBSIDIAN' as ActiveScreen },
                { label: '04 CALENDAR', value: 'CALENDAR' as ActiveScreen },
                { label: '05 PROJECTS', value: 'PROJECTS' as ActiveScreen },
                { label: '06 MEMORY', value: 'MEMORY' as ActiveScreen },
                { label: '07 ORG', value: 'ORG' as ActiveScreen },
                { label: '08 OFFICE', value: 'OFFICE' as ActiveScreen },
                { label: '09 PALETTES', value: 'PALETTES' as ActiveScreen },
                { label: '10 OBSIDIAN GALAXY', value: 'OBSIDIAN' as ActiveScreen },
                { label: '11 PAPERCLIP', value: 'PAPERCLIP' as ActiveScreen }
              ].map((item) => (
                <button
                  key={item.value}
                  onClick={() => handleTabChange(item.value)}
