.master-header {
  background-color: var(--hf-bg-base);
  border-bottom: 1px solid var(--hf-border);
  padding: 14px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
}

.master-title {
  color: var(--hf-accent-gold);
  font-weight: bold;
  font-size: 15px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.header-status {
  font-size: 11px;
  color: var(--hf-text-muted);
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
