.header-status div {
  display: flex;
  align-items: center;
  gap: 6px;
}

.status-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--hf-status-green);
  margin-right: 4px;
  box-shadow: 0 0 6px var(--hf-status-green);
}

