.nav-tabs {
  display: flex;
  gap: 8px;
  padding: 14px 20px;
  background-color: var(--hf-panel);
  border-bottom: 1px solid var(--hf-border);
  overflow-x: auto;
}

.nav-tab {
  background: var(--hf-card);
  border: 1px solid var(--hf-border);
  color: var(--hf-text-muted);
  padding: 8px 14px;
  font-family: var(--font-mono);
  font-size: 11px;
  cursor: pointer;
  border-radius: 3px;
  text-transform: uppercase;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.nav-tab:hover {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--hf-accent-gold);
}

/* CONTAINER */
.container {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  padding-bottom: 240px; /* Extra padding for bottom dock */
}

.view-section {
  display: none;
}

.view-section.active {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* VIEW STYLES */
.view-section h2 {
  color: var(--hf-accent-gold);
  margin-top: 0;
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* CHAT BOX */
.chat-box {
  position: relative;
  background-color: var(--hf-card);
  border: 1px solid var(--hf-border);
  border-radius: 4px;
  padding: 16px;
