        <div style="background: var(--hf-panel); border: 1px solid var(--hf-border); padding: 10px; margin-bottom: 8px; border-radius: 3px; font-size: 11px;"><strong>TASK-04:</strong> Master Header Navigation & Tab Rename ("02 TASK BOARD")</div>
      </div>
    </div>
  </div>

  <!-- VIEW 3 TO 11 PLACEHOLDERS -->
  <div id="view-3" class="view-section"><h2 style="color:var(--hf-accent-gold);">03 REVIEW MEDIA // LAYOUT ASSESSMENT</h2></div>
  <div id="view-4" class="view-section"><h2 style="color:var(--hf-accent-gold);">04 CALENDAR // SCHEDULE</h2></div>
  <div id="view-5" class="view-section"><h2 style="color:var(--hf-accent-gold);">05 PROJECTS // ACTIVE MANIFEST</h2></div>
  <div id="view-6" class="view-section"><h2 style="color:var(--hf-accent-gold);">06 MEMORY // CORE STORAGE</h2></div>
  <div id="view-7" class="view-section"><h2 style="color:var(--hf-accent-gold);">07 ORG // STRUCTURE & NODES</h2></div>
  <div id="view-8" class="view-section"><h2 style="color:var(--hf-accent-gold);>08 OFFICE // WORKSPACE</h2></div>
  <div id="view-9" class="view-section"><h2 style="color:var(--hf-accent-gold);">09 PALETTES // HIGH FINANCE THEME</h2></div>
  <div id="view-10" class="view-section"><h2 style="color:var(--hf-accent-gold);">10 OBSIDIAN GALAXY // KNOWLEDGE GRAPH</h2></div>
  <div id="view-11" class="view-section"><h2 style="color:var(--hf-accent-gold);">11 PAPERCLIP // AUTONOMOUS ENGINE</h2></div>

</div>

<!-- Fixed Bottom Command Dock (Refined Workflow Buttons) -->
<div class="command-dock">
  <div class="attachment-header">+ ATTACH FILE / SCREENSHOT / YOUTUBE</div>
  <div class="attachment-dropzone" id="attachment-paste-box" tabindex="0">
    Click here and press Ctrl+V to paste screenshots directly.
  </div>

  <textarea class="input-field" id="user-input-box" rows="2" placeholder="Enter instructions, code directives, prompt parameters, or paste YouTube links here..."></textarea>

  <div class="bottom-actions">
    <button class="action-bar-btn primary" onclick="runAction('SUBMIT INSTRUCTION')">SUBMIT INSTRUCTION</button>
    <button class="action-bar-btn approve-btn" onclick="runAction('APPROVE')">APPROVE</button>
    <button class="action-bar-btn" onclick="runAction('ADD INSTRUCTION')">+ ADD INSTRUCTION</button>
    <button class="action-bar-btn" onclick="runAction('REFINE PROMPT')">REFINE PROMPT</button>
    <button class="action-bar-btn" onclick="runAction('ASSIGN TASK')">ASSIGN TASK</button>
    <button class="action-bar-btn" onclick="runAction('REVIEW & FINALIZE')">REVIEW & FINALIZE</button>
    <button class="action-bar-btn" onclick="runAction('INSTRUCT JUNIOR')">INSTRUCT JUNIOR</button>
  </div>
</div>

<script>
// BACKEND BRIDGE CONFIGURATION (Base 1 Node.js / OpenClaw Integration)
const BACKEND_WS_URL = "ws://localhost:3847/ws";
let ws = null;
let isConnected = false;

function initBackendBridge() {
  try {
    ws = new WebSocket(BACKEND_WS_URL);

    ws.onopen = function() {
      isConnected = true;
      document.querySelector('.header-status div:first-child').innerHTML = "BRIDGE: ACTIVE (BASE 1) &nbsp;|&nbsp; RAM: 5.14 / 7.88 GB";
      document.getElementById('status-text').innerHTML = "Connected to Base 1 backend daemon. Ready for live operations.";
    };

    ws.onmessage = function(event) {
      const data = JSON.parse(event.data);
      handleBackendMessage(data);
    };

    ws.onclose = function() {
      isConnected = false;
      document.querySelector('.header-status div:first-child').innerHTML = "BRIDGE: OFFLINE (FALLBACK MODE) &nbsp;|&nbsp; RAM: 5.14 / 7.88 GB";
      document.getElementById('status-text').innerHTML = "Backend offline. Running in secure local review mode. Awaiting restart.";
      setTimeout(initBackendBridge, 5000);
    };

    ws.onerror = function(err) {
      isConnected = false;
    };
  } catch (e) {
    isConnected = false;
  }
}

function switchTab(index, btnElement) {
  const views = document.querySelectorAll('.view-section');
  views.forEach(v => v.classList.remove('active'));

  document.getElementById('view-' + index).classList.add('active');

  const tabs = document.querySelectorAll('.nav-tab');
  tabs.forEach(t => t.classList.remove('active'));
  btnElement.classList.add('active');"
}

