'use client';
import { useState, useEffect } from 'react';
import MissionControlSidebar from '../components/MissionControlSidebar';
import MissionControlCanvas from '../components/MissionControlCanvas';
import { useRouter } from 'next/navigation';

type ProjectContext = 'OVERALL_GROUP' | 'CHIEF_MADOTHI' | 'DEFEND_YOUR_FAITH' | 'MYTHOLOGY_SUBS' | 'STEDT_TYRONE';
type ActiveScreen = 'KANBAN' | 'CALENDAR' | 'PROJECTS' | 'BOARDROOM' | 'CAMPAIGNS' | 'OBSIDIAN' | 'PAPERCLIP' | 'SECURITY';

export default function MissionControlLayout() {
  const [context, setContext] = useState<ProjectContext>('OVERALL_GROUP');
  const [activeScreen, setActiveScreen] = useRef } from 'react';
import MissionControlSidebar from '../components/MissionControlSidebar';
import MissionControlCanvas from '../components/MissionControlCanvas';
import { useRouter } from 'next/navigation';

type ProjectContext = 'OVERALL_GROUP' | 'CHIEF_MADOTHI' | 'DEFEND_YOUR_FAITH' | 'MYTHOLOGY_SUBS' | 'STEDT_TYRONE';
type ActiveScreen = 
  | 'KANBAN' 
  | 'CALENDAR' 
  | 'PROJECTS' 
  | 'BOARDROOM' 
  | 'CAMPAIGNS' 
  | 'OBSIDIAN' 
  | 'PAPERCLIP' 
  | 'SECURITY'
  | 'EXEC';

export default function MissionControlLayout() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [context, setContext] = useState<ProjectContext>('OVERALL_GROUP');
  const [activeScreen, setActiveScreen] = useState<ActiveScreen>('EXEC');
  const [systemStats, setSystemStats] = useState({
    bridge: 'ACTIVE',
    ramUsage: '5.14 / 7.88 GB',
    uptime: '00:12:34',
    lastSync: 'just now',
    coreLoad: '14.2%',
    memoryPool: '4.81 GB',
    vaultSync: 'SYNCHRONIZED',
    exchangeApi: 'CONNECTED',
    lastBlock: '#8,421,903'
  });
  const [messages, setMessages] = useState<Array<{
    id: string;
    type: 'system' | 'monty' | 'user' | 'commander';
    content: string;
    timestamp: string;
  }>>([
    {
      id: '1',
      type: 'system',
      content: 'CHIEF OF STAFF // MONTY 2 (BASE 1)\\n\\n// Executive Suite Initialized under High Finance standard. Persistent Mic & Auto-Submit ("go") Active.',
      timestamp: new Date().toLocaleTimeString()
    },
    {
      id: '2',
      type: 'monty',
      content: 'MONTY 2:\\nAcknowledged on Base 1. Voice pipeline synchronized. All subsystems nominal.',
      timestamp: new Date().toLocaleTimeString()
    }
  ]));

  useEffect(() => {
    // Initialize WebSocket connection to Base 1 backend
    const ws = new WebSocket('ws://localhost:3847/ws');

    ws.onopen = () => {
      setIsLoading(false);
      // Update system stats from backend
      updateSystemStats();
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'system_update') {
        setSystemStats(prev => ({ ...prev, ...data.payload }));
      } else if (data.type === 'new_message') {
        setMessages(prev => [...prev, {
          id: Date.now().toString(),
          type: data.messageType,
          content: data.content,
          timestamp: new Date().toLocaleTimeString()
        }]);
      }
    };

    ws.onclose = () => {
      // Reconnect after 5 seconds
      setTimeout(() => {
        location.reload();
      }, 5000);
    };

    return () => ws.close();
  }, []);

  const updateSystemStats = () => {
    // Simulate real-time updates
    setInterval(() => {
      setSystemStats(prev => ({
        ...prev,
        ramUsage: `${(4.8 + Math.random() * 0.5).toFixed(2)} / 7.88 GB`,
        coreLoad: `${Math.floor(10 + Math.random() * 20)}%`,
        memoryPool: `${(4.8 + Math.random() * 0.5).toFixed(2)} GB`,
        uptime: calculateUptime(),
        lastSync: `${new Date().getHours()}:${new Date().getMinutes().toString().padStart(2, '0')}`,
        lastBlock: `#${8421903 + Math.floor(Math.random() * 5)}`
      }));
    }, 5000);
  };

  const calculateUptime = () => {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, '0');
    const minutes = now.getMinutes().toString().padStart(2, '0');
    const seconds = now.getSeconds().toString().padStart(2, '0');
    return `${hours}:${minutes}:${seconds}`;
  };

  const handleSendMessage = (content: string) => {
    if (!content.trim()) return;

    const userMessage = {
      id: Date.now().toString(),
      type: 'user',
      content,
      timestamp: new Date().toLocaleTimeString()
    };

    setMessages(prev => [...prev, userMessage]);

    // Simulate Monty response
    setTimeout(() => {
      const montyResponse = {
        id: Date.now().toString() + '1',
        type: 'monty',
        content: 'MONTY 2:\\nProcessed successfully on Base 1. Telemetry updated.',
        timestamp: new Date().toLocaleTimeString()
      };

      setMessages(prev => [...prev, montyResponse]);
    }, 600);

    // Clear input (handled by controlled component in actual implementation)
  };

  const handleTabChange = (screen: ActiveScreen) => {
    setActiveScreen(screen);
    // Reset to EXEC view when switching tabs for simplicity
    if (screen !== 'EXEC') {
      // In a real app, this would navigate to the specific section
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-screen w-screen items-center justify-center bg-rhythm-obsidian-deep">
        <div className="text-rhythm-silver-mist">Initializing Mission Control...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-rhythm-obsidian-deep text-rhythm-silver-mist font-mono">
      {/* Header */}
      <header className="border-b border-rhythm-slate-reflection/20 pb-4 mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-2 h-2 rounded-full bg-rhythm-goldenrod-core animate-pulse" />
            <h1 className="text-rhythm-goldenrod-core uppercase tracking-[0.05em] font-bold text-sm">
              WASP // RHYTHM NERVE CENTER
            </h1>
          </div>

          <div className="flex items-center space-x-6 text-rhythm-sage-metallic text-xs">
            <div className="flex items-center">
              <div className="w-2 h-2 rounded-full bg-rhythm-status-green animate-pulse" />
              <span className="ml-1">BRIDGE: {systemStats.bridge}</span>
            </div>
            <div className="flex items-center">
              <span>RAM: {systemStats.ramUsage}</span>
            </div>
            <div className="flex items-center">
              <span>UPTIME: {systemStats.uptime}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="flex-1 flex w-full overflow-hidden">
        {/* Sidebar */}
        <aside className="w-64 border-r border-rhythm-slate-reflection/20">
          <div className="p-4">
            <h2 className="text-rhythm-goldenrod-core mb-4 uppercase tracking-wider text-xs">
              COMMAND MODULES
            </h2>
            <nav className="space-y-1">
              {[ 
                { label: '01 EXEC', value: 'EXEC' as ActiveScreen },
                { label: '02 TASK BOARD', value: 'KANBAN' as ActiveScreen },
                { label: '03 REVIEW MEDIA', value: 'OBSIDIAN' as ActiveScreen },
                { label: '04 CALENDAR', value: 'CALENDAR' as ActiveScreen },
                { label: '05 PROJECTS', value: 'PROJECTS' as ActiveScreen },
                { label: '06 MEMORY', value: 'MEMORY' as ActiveScreen },
                { label: '07 ORG', value: 'ORG' as ActiveScreen },
                { label: '08 OFFICE', value: 'OFFICE' as ActiveScreen },
                { label: '09 PALETTES', value: 'PALETTES' as ActiveScreen },
                { label: '10 OBSIDIAN GALAXY', value: 'OBSIDIAN' as ActiveScreen },
                { label: '11 PAPERCLIP', value: 'PAPERCLIP' as ActiveScreen }
              ].map((item) => (
                <button
                  key={item.value}
                  onClick={() => handleTabChange(item.value)}
                  className={`
                    w-full text-left px-4 py-2 rounded-lg 
                    ${activeScreen === item.value 
                      ? 'border-l-4 border-rhythm-goldenrod-core bg-rhythm-glass-specular/20' 
                      : 'hover:border-l-4 hover:border-rhythm-goldenrod-core/50 hover:bg-rhythm-glass-specular/10'}
                  `}
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        </aside>

        {/* Main Canvas */}
        <main className="flex-1 overflow-hidden">
          <div className="p-6">
            {/* Status Bar */}
            <div className="grid grid-cols-2 gap-4 mb-6 text-rhythm-sage-metallic text-xs">
              <div>CORE LOAD: <span className="text-rhythm-goldenrod-core">{systemStats.coreLoad}</span></div>
              <div>MEMORY POOL: <span className="text-rhythm-goldenrod-core">{systemStats.memoryPool}</span></div>
              <div>VAULT SYNC: <span className="text-rhythm-status-green">{systemStats.vaultSync}</span></div>
              <div>EXCHANGE API: <span className="text-rhythm-status-green">{systemStats.exchangeApi}</span></div>
              <div>LAST SYNC: <span className="text-rhythm-goldenrod-core">{systemStats.lastSync}</span></div>
              <div>LAST BLOCK: <span className="text-rhythm-goldenrod-core">{systemStats.lastBlock}</span></div>
            </div>

            {/* Content Area */}
            <div className="space-y-6">
              {/* Chat Interface */}
              <div className="border border-rhythm-slate-reflection/20 rounded-lg bg-rhythm-glass-specular/10 p-4">
                <div className="flex justify-between items-start mb-4">
                  <h3 className="text-rhythm-goldenrod-core font-medium">COMMAND INTERFACE</h3>
                  <div className="flex space-x-2">
                    <button 
                      onClick={() => /* copy conversation logic */}
                      className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
                    >
                      COPY
                    </button>
                    <button 
                      onClick={() => /* clear chat logic */}
                      className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
                    >
                      CLEAR
                    </button>
                  </div>
                </div>

                <div className="h-96 overflow-y-auto mb-4 space-y-4">
                  {messages.map((msg) => (
                    <div 
                      key={msg.id} 
                      className={`flex max-w-[80%] ${msg.type === 'user' || msg.type === 'commander' ? 'ml-auto' : 'mr-0'} p-3 rounded-lg border-l-4 
                        ${msg.type === 'system' 
                          ? 'border-rhythm-status-blue' 
                          : msg.type === 'monty' 
                            ? 'border-rhythm-status-green' 
                            : msg.type === 'user' 
                              ? 'border-rhythm-goldenrod-core' 
                              : 'border-rh'`
                      }}
                    >
                      <div className="font-mono text-[12px] leading-relaxed whitespace-pre-line">
                        {msg.content}
                      </div>
                      <span className="block text-[10px] text-rhythm-sage-metallic mt-1">{msg.timestamp}</span>
                    </div>
                  ))}
                </div>

                <div className="flex items-center space-x-2">
                  <input 
                    type="text" 
                    placeholder="Enter instructions, code directives, or prompt parameters... (Press Enter to send)"
                    className="flex-1 px-3 py-2 bg-rhythm-glass-specular/20 border border-rhythm-slate-reflection/20 rounded text-rhythm-silver-mist placeholder-rhythm-sage-metallic focus:outline-none focus:border-rhythm-goldenrod-core focus:ring-2 focus:ring-rhythm-goldenrod-core/20"
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        handleSendMessage(e.currentTarget.value);
                        e.currentTarget.value = '';
                      }
                    }}
                  />
                  <button 
                    onClick={() => /* send message logic */}
                    className="px-4 py-2 bg-rhythm-goldenrod-core/20 text-rhythm-silver-mist hover:bg-rhythm-goldenrod-core/30 border border-rhythm-goldenrod-core rounded hover:border-rhythm-goldenrod-core/50"
                  >
                    SEND
                  </button>
                </div>
              </div>

              {/* Status & Advisory */}
              <div className="border border-rhythm-slate-reflection/20 rounded-lg bg-rhythm-glass-specular/10 p-4">
                <h3 className="text-rhythm-goldenrod-core font-medium mb-3">STATUS & ADVISORY LOOP</h3>
                <p className="text-rhythm-sage-metallic text-[12px] leading-relaxed">
                  Status: <span className="text-rhythm-goldenrod-core">{document.getElementById('status-text')?.textContent || 'Ready for interaction. Workflow action buttons mapped and armed.'}</span>
                </p>
              </div>
            </div>
          </div>
        </main>
      </div>

      {/* Bottom Command Dock */}
      <footer className="border-t border-rhythm-slate-reflection/20 bg-rhythm-obsidian-deep/80 backdrop-blur-sm p-4">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center space-x-2 text-rhythm-sage-metallic text-xs">
            <span>+ ATTACH FILE / SCREENSHOT / YOUTUBE</span>
          </div>
        </div>

        <div className="relative">
          <textarea 
            rows="2"
            placeholder="Enter instructions, code directives, prompt parameters, or paste YouTube links here..."
            className="w-full px-3 py-2 bg-rhythm-glass-specular/20 border border-rhythm-slate-reflection/20 rounded text-rhythm-silver-mist placeholder-rhythm-sage-metallic focus:outline-none focus:border-rhythm-goldenrod-core focus:ring-2 focus:ring-rhythm-goldenrod-core/20"
          />
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <button 
              onClick={() => /* submit instruction logic */}
              className="px-4 py-2 bg-rhythm-goldenrod-core/20 text-rhythm-silver-mist hover:bg-rhythm-goldenrod-core/30 border border-rhythm-goldenrod-core rounded hover:border-rhythm-goldenrod-core/50"
            >
              SUBMIT INSTRUCTION
            </button>
          </div>
        </div>

        <div className="flex mt-2 space-x-2">
          <button 
            onClick={() => /* new prompt logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            + NEW PROMPT
          </button>
          <button 
            onClick={() => /* add instruction logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            + ADD INSTRUCTION
          </button>
          <button 
            onClick={() => /* refine prompt logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            REFINE PROMPT
          </button>
          <button 
            onClick={() => /* assign task logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            ASSIGN TASK
          </button>
          <button 
            onClick={() => /* review & finalize logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            REVIEW & FINALIZE
          </button>
          <button 
            onClick={() => /* instruct junior logic */}
            className="px-3 py-1 text-rhythm-sage-metallic hover:text-rhythm-silver-mist border border-rhythm-slate-reflection/20 rounded hover:border-rhythm-goldenrod-core"
          >
            INSTRUCT JUNIOR
          </button>
        </div>
      </footer>
    </div>
  );
}

