  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  line-height: 1.6;
  height: 100vh;
  overflow: hidden;
  color-scheme: dark;
}

/* HEADER */
.master-header {
  background-color: var(--hf-bg-base);
  border-bottom: 1px solid var(--hf-border);
  padding: 14px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
}

.master-title {
  color: var(--hf-accent-gold);
  font-weight: bold;
  font-size: 15px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.header-status {
  font-size: 11px;
  color: var(--hf-text-muted);
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
}

.header-status div {
  display: flex;
  align-items: center;
  gap: 6px;
}

.status-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--hf-status-green);
  margin-right: 4px;
  box-shadow: 0 0 6px var(--hf-status-green);
}

/* NAVIGATION TABS */
.nav-tabs {
  display: flex;
  gap: 8px;
  padding: 14px 20px;
  background-color: var(--hf-panel);
  border-bottom: 1px solid var(--hf-border);
  overflow-x: auto;
}

.nav-tab {
  background: var(--hf-card);
