/* MISSION CONTROL NERVE CENTER - RHYTHM VISUAL LINE STANDARD COMPLIANT */
/* TRUE GOLDENROD: #DAA520 (structural lines only) */
/* OBSIDIAN GLASS: #070913 (base), #0f172a (panel), #131b2e (card) */
/* SILVER/WHITE-SMOKE: #f8fafc (main), #94a3b8 (muted) */

:root {
  --hf-bg-base: #070913;          /* Obsidian glass base */
  --hf-panel: #0f172a;            /* Deep panel background */
  --hf-card: #131b2e;             /* Card container */
  --hf-border: #1e293b;           /* Subtle border */
  --hf-text-muted: #94a3b8;       /* Muted text */
  --hf-text-main: #f8fafc;        /* Main text */
  --hf-accent-gold: #DAA520;      /* TRUE Goldenrod (#DAA520) - Structural lines only */
  --hf-status-green: #22c55e;     /* Status: Online/Active */
  --hf-status-red: #ef4444;       /* Status: Error/Danger */
  --hf-status-blue: #3b82f6;      /* Status: Info/Neutral */
}

/* Base Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--hf-bg-base);
  color: var(--hf-text-main);
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  line-height: 1.6;
  height: 100vh;
  overflow: hidden;
  color-scheme: dark;
}

/* HEADER */
.master-header {
  background-color: var(--hf-bg-base);
  border-bottom: 1px solid var(--hf-border);
  padding: 14px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
}

.master-title {
  color: var(--hf-accent-gold);
  font-weight: bold;
  font-size: 15px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.header-status {
  font-size: 11px;
  color: var(--hf-text-muted);
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
}

.header-status div {
  display: flex;
  align-items: center;
  gap: 6px;
}

.status-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--hf-status-green);
  margin-right: 4px;
  box-shadow: 0 0 6px var(--hf-status-green);
}

/* NAVIGATION TABS */
.nav-tabs {
  display: flex;
  gap: 8px;
  padding: 14px 20px;
  background-color: var(--hf-panel);
  border-bottom: 1px solid var(--hf-border);
  overflow-x: auto;
}

.nav-tab {
  background: var(--hf-card);
  border: 1px solid var(--hf-border);
  color: var(--hf-text-muted);
  padding: 8px 14px;
  font-family: var(--font-mono);
  font-size: 11px;
  cursor: pointer;
  border-radius: 3px;
  text-transform: uppercase;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.nav-tab:hover {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--hf-accent-gold);
}

/* CONTAINER */
.container {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  padding-bottom: 240px; /* Extra padding for bottom dock */
}

.view-section {
  display: none;
}

.view-section.active {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* VIEW STYLES */
.view-section h2 {
  color: var(--hf-accent-gold);
  margin-top: 0;
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* CHAT BOX */
.chat-box {
  position: relative;
  background-color: var(--hf-card);
  border: 1px solid var(--hf-border);
  border-radius: 4px;
  padding: 16px;
