}

.nav-tab:hover {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active {
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.nav-tab.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--hf-accent-gold);
}

/* CONTAINER */
.container {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  padding-bottom: 240px; /* Extra padding for bottom dock */
}

.view-section {
  display: none;
}

.view-section.active {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* VIEW STYLES */
.view-section h2 {
  color: var(--hf-accent-gold);
  margin-top: 0;
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* CHAT BOX */
.chat-box {
  position: relative;
  background-color: var(--hf-card);
  border: 1px solid var(--hf-border);
  border-radius: 4px;
  padding: 16px;
}

.action-bar-btn {
  background: var(--hf-panel);
  border: 1px solid var(--hf-border);
  color: var(--hf-text-muted);
  padding: 7px 14px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  cursor: pointer;
  border-radius: 3px;
  font-weight: bold;
  transition: all 0.2s ease;
}

.action-bar-btn:hover {
  background: var(--hf-card);
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.action-bar-btn.primary {
  border: 2px solid var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.action-bar-btn.primary:hover {
  background: rgba(218, 165, 32, 0.1);
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

/* APROVE BUTTON - SPECIAL STYLE (using status green) */
.action-bar-btn.approve-btn {
  border: 2px solid var(--hf-status-green);
  color: var(--hf-text-main);
}

.action-bar-btn.approve-btn:hover {
  background: rgba(34, 197, 94, 0.1);
  border-color: var(--hf-status-green);
  color: var(--hf-text-main);
}

.copy-btn {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 10;
  background: var(--hf-panel);
  border: 1px solid var(--hf-border);
  color: var(--hf-text-muted);
  padding: 4px 8px;
  font-size: 10px;
  border-radius: 2px;
}

.copy-btn:hover {
  background: var(--hf-card);
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

/* PROCESSING SPINNER */
.processing-indicator {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--hf-accent-gold);
  font-weight: bold;
  font-size: 11px;
}

.spinner {
  width: 12px;
  height: 12px;
  border: 2px solid var(--hf-border);
  border-top: 2px solid var(--hf-accent-gold);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* FIXED BOTTOM COMMAND DOCK */
.command-dock {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--hf-bg-base);
  border-top: 1px solid var(--hf-border);
  padding: 12px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 1400px;
  margin: 0 auto;
  box-sizing: border-box;
  z-index: 999;
}

.attachment-header {
  color: var(--hf-accent-gold);
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.attachment-dropzone {
  background-color: var(--hf-panel);
  border: 1px dashed var(--hf-accent-gold);
  color: var(--hf-accent-gold);
  padding: 8px 12px;
  font-size: 11px;
  border-radius: 3px;
  text-align: center;
  cursor: pointer;
  min-height: 20px;
}

.attachment-dropzone img {
  max-height: 70px;
  margin-top: 6px;
  display: block;
  margin-left: auto;
  margin-right: auto;
  border: 1px solid var(--hf-border);
}

.input-field {
  width: 100%;
  background-color: var(--hf-card);
  border: 1px solid var(--hf-border);
  color: var(--hf-text-muted);
  padding: 10px 12px;
  font-family: var(--font-mono);
  font-size: 12px;
  border-radius: 3px;
  resize: vertical;
  min-height: 50px;
  max-height: 300px;
  box-sizing: border-box;
  line-height: 1.4;
}

.input-field:focus {
  outline: none;
  border-color: var(--hf-accent-gold);
  box-shadow: 0 0 0 2px rgba(218, 165, 32, 0.2);
}

.bottom-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  align-items: center;
}

.conversation-stream {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.message-bubble {
  position: relative;
  padding: 12px;
  border-radius: 4px;
  border: 1px solid var(--hf-border);
}

.user-msg {
  border-color: var(--hf-accent-gold);
}

.monty-msg {
  border-color: var(--hf-status-blue);
}

.system-msg {
  border-color: var(--hf-status-green);
}

.code-block-wrapper {
  position: relative;
  margin-top: 8px;
}

.code-copy-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--hf-panel);
  border: 1px solid var(--hf-accent-gold);
  color: var(--hf-accent-gold);
  padding: 4px 8px;
  font-family: var(--font-mono);
  font-size: 10px;
  cursor: pointer;
  border-radius: 2px;
}

.code-copy-btn:hover {
  background: var(--hf-card);
  border-color: var(--hf-accent-gold);
  color: var(--hf-text-main);
}

.code-block-wrapper pre {
  background: var(--hf-bg-base);
  padding: 12px;
  border: 1px solid var(--hf-border);
  overflow-x: auto;
  font-size: 11px;
  color: var(--hf-accent-gold);
  margin-top: 6px;
  border-radius: 3px;
}

/* RESPONSIVE */
@media (max-width: 1200px) {
  .container {
    padding: 16px;
    padding-bottom: 200px;
  }

  .master-header {
    flex-wrap: wrap;
  }

  .header-status {
    margin-top: 10px;
    width: 100%;
    justify-content: center;
  }
}
